NS.GlobalStrings["NEWBIE_TOOLTIP_MANABAR0"] = "The amount of mana you currently have. Players require mana in order to cast spells. Mana automatically regenerates if you have not cast a spell in the past five seconds."
NS.GlobalStrings["NEWBIE_TOOLTIP_MANABAR1"] = "Warriors (and Druids in Bear Form or Dire Bear Form) require Rage in order to use their abilities."
NS.GlobalStrings["NEWBIE_TOOLTIP_MANABAR2"] = "Hunters require focus to use their abilities.  Focus generates while standing still."
