NS.GlobalStrings["NEWBIE_TOOLTIP_PLAYEROPTIONS"] = "Right-click to bring up special commands for interacting with another player. You can inspect their equipment, issue a party invite, initiate a trade, or challenge a player to a duel. A group leader can promote or remove that player from the group."
